package com.bank.reverse;

import java.util.logging.Logger;

// Reverses a reference code without StringBuilder for National Bank of India.
public class ReferenceReverser {
    private static final Logger log = Logger.getLogger(ReferenceReverser.class.getName());

    // Two-pointer swap on a char array. O(n) time, O(n) space (String is immutable).
    public String reverse(String code) {
        if (code == null) {
            throw new IllegalArgumentException("code must not be null");
        }
        char[] chars = code.toCharArray();     // mutable working buffer
        int left = 0;
        int right = chars.length - 1;
        while (left < right) {                 // odd middle untouched; even pointers cross
            char tmp = chars[left];            // swap ends
            chars[left] = chars[right];
            chars[right] = tmp;
            left++;
            right--;
        }
        String reversed = new String(chars);   // rebuild String from buffer
        log.info(() -> "Reversed '" + code + "' → '" + reversed + "'");
        return reversed;
    }
}
