package com.bank.reverse;

import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

// Runnable demo: reverse odd and even length reference codes.
public class ReferenceReverserDemo {
    private static final Logger log = Logger.getLogger(ReferenceReverserDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        ReferenceReverser reverser = new ReferenceReverser();

        String odd = "TXF123";          // even length actually, show both
        log.info(() -> "Even result = " + reverser.reverse(odd));

        String oddLen = "SAV2001";      // odd length, middle char fixed
        log.info(() -> "Odd result = " + reverser.reverse(oddLen));
    }
}
